// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListGames List game sessions
	// (GET /admin/games)
	ListGames(ctx context.Context, request ListGamesRequestObject) (ListGamesResponseObject, error)
	// CreateGame Create a game session from a quiz
	// (POST /admin/games)
	CreateGame(ctx context.Context, request CreateGameRequestObject) (CreateGameResponseObject, error)
	// GetGame Get full game detail (admin view, includes correct answers)
	// (GET /admin/games/{gameId})
	GetGame(ctx context.Context, request GetGameRequestObject) (GetGameResponseObject, error)
	// EndGame Force-end a game
	// (POST /admin/games/{gameId}/end)
	EndGame(ctx context.Context, request EndGameRequestObject) (EndGameResponseObject, error)
	// GetAdminLeaderboard Leaderboard snapshot for the admin dashboard
	// (GET /admin/games/{gameId}/leaderboard)
	GetAdminLeaderboard(ctx context.Context, request GetAdminLeaderboardRequestObject) (GetAdminLeaderboardResponseObject, error)
	// AdvanceGame End the current question and advance to the next one, or end the game if exhausted
	// (POST /admin/games/{gameId}/next-question)
	AdvanceGame(ctx context.Context, request AdvanceGameRequestObject) (AdvanceGameResponseObject, error)
	// StartGame Start a game (lobby -> in_progress)
	// (POST /admin/games/{gameId}/start)
	StartGame(ctx context.Context, request StartGameRequestObject) (StartGameResponseObject, error)
	// ListQuizzes List quizzes
	// (GET /admin/quizzes)
	ListQuizzes(ctx context.Context, request ListQuizzesRequestObject) (ListQuizzesResponseObject, error)
	// CreateQuiz Create a quiz
	// (POST /admin/quizzes)
	CreateQuiz(ctx context.Context, request CreateQuizRequestObject) (CreateQuizResponseObject, error)
	// DeleteQuiz Delete a quiz
	// (DELETE /admin/quizzes/{quizId})
	DeleteQuiz(ctx context.Context, request DeleteQuizRequestObject) (DeleteQuizResponseObject, error)
	// GetQuiz Get a quiz with its questions
	// (GET /admin/quizzes/{quizId})
	GetQuiz(ctx context.Context, request GetQuizRequestObject) (GetQuizResponseObject, error)
	// UpdateQuiz Update a quiz
	// (PATCH /admin/quizzes/{quizId})
	UpdateQuiz(ctx context.Context, request UpdateQuizRequestObject) (UpdateQuizResponseObject, error)
	// ListQuestions List a quiz's questions, in order
	// (GET /admin/quizzes/{quizId}/questions)
	ListQuestions(ctx context.Context, request ListQuestionsRequestObject) (ListQuestionsResponseObject, error)
	// CreateQuestion Add a question to a quiz
	// (POST /admin/quizzes/{quizId}/questions)
	CreateQuestion(ctx context.Context, request CreateQuestionRequestObject) (CreateQuestionResponseObject, error)
	// ReorderQuestions Reorder a quiz's questions
	// (PUT /admin/quizzes/{quizId}/questions/order)
	ReorderQuestions(ctx context.Context, request ReorderQuestionsRequestObject) (ReorderQuestionsResponseObject, error)
	// DeleteQuestion Delete a question
	// (DELETE /admin/quizzes/{quizId}/questions/{questionId})
	DeleteQuestion(ctx context.Context, request DeleteQuestionRequestObject) (DeleteQuestionResponseObject, error)
	// GetQuestion Get a question
	// (GET /admin/quizzes/{quizId}/questions/{questionId})
	GetQuestion(ctx context.Context, request GetQuestionRequestObject) (GetQuestionResponseObject, error)
	// UpdateQuestion Update a question
	// (PATCH /admin/quizzes/{quizId}/questions/{questionId})
	UpdateQuestion(ctx context.Context, request UpdateQuestionRequestObject) (UpdateQuestionResponseObject, error)
	// JoinGame Join a game by its join code
	// (POST /games/join)
	JoinGame(ctx context.Context, request JoinGameRequestObject) (JoinGameResponseObject, error)
	// GetPublicGame Public lookup of a game by join code
	// (GET /games/{code})
	GetPublicGame(ctx context.Context, request GetPublicGameRequestObject) (GetPublicGameResponseObject, error)
	// GetPublicLeaderboard Public leaderboard snapshot
	// (GET /games/{code}/leaderboard)
	GetPublicLeaderboard(ctx context.Context, request GetPublicLeaderboardRequestObject) (GetPublicLeaderboardResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

